<?php
require __DIR__.'/layout.php'; require __DIR__.'/pes_master.php'; $user=require_role(['superadmin']); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST') { pes_check_csrf(); $id=(int)($_POST['id']??0); $pass=(string)($_POST['password']??''); if(strlen($pass)<8) $error='Password minimal 8 karakter.'; else { $q=db()->prepare('UPDATE users SET password_hash=? WHERE id=?'); $q->execute([password_hash($pass,PASSWORD_DEFAULT),$id]); flash('success','Password akun diperbarui.'); redirect('user_passwords.php'); } }
render_header('Ganti Password User'); if($msg=flash('success')) echo '<div class="alert alert-success">'.e($msg).'</div>'; if($error) echo '<div class="alert alert-danger">'.e($error).'</div>';
?>
<div class="card card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(pes_csrf())?>"><div class="form-group"><label>Akun</label><select class="form-control" name="id" required><?php foreach(db()->query('SELECT id,username,name,role,satker FROM users ORDER BY satker,role,username') as $r): ?><option value="<?=e($r['id'])?>"><?=e($r['username'].' — '.$r['name'].' / '.$r['role'].' / '.$r['satker'])?></option><?php endforeach ?></select></div><div class="form-group"><label>Password baru</label><input class="form-control" type="password" name="password" minlength="8" required autocomplete="new-password"></div><button class="btn btn-primary">Simpan Password</button></form></div><?php render_footer(); ?>
